import org.springframework.stereotype.Component;
import java.util.concurrent.atomic.AtomicInteger;

/**
 * A singleton Spring bean that generates sequential request IDs of the
 * form "REQ-<currentUserId>-<sequence>" for the currently-processing
 * request. Because this bean is a singleton (Spring's default scope), it
 * is shared across all concurrently-handled HTTP requests in the
 * application -- it must never hold per-request mutable state as an
 * instance field.
 */
@Component
public class RequestIdGenerator {

    private final AtomicInteger sequence = new AtomicInteger(0);

    /** 
     * To avoid holding per-request mutable state in a singleton, 
     * we use ThreadLocal to ensure that the currentUserId and the 
     * sequence are isolated to the specific thread handling the request.
     */
    private final ThreadLocal<String> threadUserId = new ThreadLocal<>();
    private final ThreadLocal<Integer> threadSequence = ThreadLocal.withInitial(() -> 0);

    /** Called once at the start of handling a request for the given user. */
    public void startRequest(String userId) {
        this.threadUserId.set(userId);
    }

    /** Called to produce the next ID for the request started above. */
    public String generateId() {
        int currentSeq = threadSequence.get();
        int nextSeq = currentSeq + 1;
        threadSequence.set(nextSeq);

        String userId = threadUserId.get();
        if (userId == null) {
            throw new IllegalStateException("startRequest must be called before generateId");
        }

        return "REQ-" + userId + "-" + nextSeq;
    }
}
